<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;

final class ProductionPrepareFormRenderer implements PrepareFormRenderer,CompatibilityPrepareFormRenderer
{
    public function render(HttpUser $user,array $f):string
    {
        $e=[PilotView::class,'e'];$id=$e($f['id']);$selected=$f['selected']??[];$selectedInstallers=\array_map('strval',$selected['installers']??[]);$engineer=$f['engineer']??null;
        $installerData='';foreach($f['installers']as$x){$value=(string)$x['tabId'];$tab=\str_pad($value,6,'0',STR_PAD_LEFT);$installerData.='<span data-id="'.$e($value).'" data-name="'.$e($x['fio']).'" data-tab="'.$e($tab).'" data-position="'.$e($x['position']).'" data-busy="" data-selected="'.(\in_array($value,$selectedInstallers,true)?'1':'0').'"></span>';}
        $command=isset($f['csrfToken']);$canUpload=$command&&($f['canUploadOriginal']??false);$route='/pilot/objects/'.$id.'/assignment-order/prepare';$hidden=$command?'<input type="hidden" name="csrfToken" value="'.$e($f['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($f['processRevision']).'">':'';
        $summary='<div class="fm2-order-object"><strong>Объект монтажа № '.$id.'</strong><span>'.$e($f['registrationNumber']).' · '.$e($f['address']).', подъезд '.$e($f['entrance']).'</span><small>Плановый период: '.$e($f['plannedStartDate']).' — '.$e($f['plannedFinishDate']).'</small></div>';
        $flash=$f['flash']??null;$notice=$flash?'<div class="fm2-alert" role="status"><a href="#'.($e($flash['field']??'form-errors')).'">'.$e($flash['message']).'</a></div>':'';
        $installers=$f['installers']===[]?'<div class="shlz-empty-state"><p>Нет допустимых монтажников.</p></div>':'<div class="fm2-picker fm2-installer-picker" data-installer-picker><div class="fm2-picker-selection" data-picker-selection aria-label="Выбранные монтажники"><span class="fm2-picker-selection-empty">Монтажники ещё не выбраны</span></div><button class="shlz-button shlz-button--primary" type="button" data-picker-open aria-controls="installer-picker" aria-expanded="false" hidden>Выбрать монтажников</button><p data-picker-fallback>Для выбора монтажников включите JavaScript или вернитесь к карточке объекта.</p><div class="fm2-picker-dialog" id="installer-picker" data-picker-dialog role="dialog" aria-label="Выбор монтажников" hidden><div class="fm2-picker-head"><div><h3>Выбор монтажников</h3><p>Поиск по ФИО или шестизначному табельному номеру</p></div></div><div class="fm2-picker-modal-selection"><strong>Выбрано</strong><div class="fm2-picker-selection" data-picker-modal-selection aria-label="Выбранные монтажники"><span class="fm2-picker-selection-empty">Пока никого</span></div></div><label class="fm2-search-field"><span>Поиск монтажника</span><input type="search" data-picker-search aria-describedby="installer-picker-result-meta" placeholder="Фамилия или табельный номер" autocomplete="off"></label><div id="installer-picker-result-meta" class="fm2-picker-result-meta" data-picker-meta aria-live="polite">Введите минимум 2 символа</div><div class="fm2-picker-results" data-picker-results role="group" aria-live="polite" aria-label="Результаты поиска"></div><footer class="fm2-picker-footer"><span data-picker-count aria-live="polite">Выбрано: 0</span></footer></div><template data-picker-data>'.$installerData.'</template><div data-picker-inputs></div></div>';
