        $templateAction=$command&&$f['installers']!==[]&&$engineer!==null?'<button class="shlz-button" type="submit" name="intent" value="template" formtarget="_blank" formnovalidate>Сформировать шаблон</button>':'';
        $upload=$canUpload?'<section class="fm2-order-upload" aria-labelledby="signed-original"><div class="fm2-order-section-head"><div><span class="fm2-order-eyebrow">Шаг 1</span><h2 id="signed-original">Подписанный оригинал</h2><p>Загрузите распоряжение в формате PDF.</p></div><span class="shlz-status shlz-status--blue">Обязательно</span></div><label class="fm2-file-drop" data-file-drop><input id="signedOriginal" type="file" name="signedOriginal" accept="application/pdf,.pdf" required data-file-input><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M5 14v5h14v-5"/></svg><span><strong><u>Выберите</u> или перетащите сюда файл</strong><small data-file-name>PDF, не более 25 МБ</small></span></label></section>':'';
        $helper='<aside class="fm2-order-helper"><div class="fm2-order-helper-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M7 3h7l4 4v14H7V3Zm7 0v5h4M10 13h5m-5 4h5"/></svg></div><div><span class="fm2-order-eyebrow">Если документа ещё нет</span><h2>Нужен шаблон?</h2><p>Сформируем PDF с выбранным составом и откроем его в новой вкладке. Это не обязательный шаг.</p></div>'.$templateAction.'</aside>';
        $changing=$f['changing']??false;$title=$changing?'Изменить состав монтажников':'Загрузить распоряжение';$intro=$changing?'Выберите полный новый состав. Предыдущее распоряжение и история закреплений сохранятся.':'Укажите состав и прикрепите подписанный оригинал.';
        $provenanceData=$f['workforceProvenance']??['mode'=>'row'];if(($provenanceData['mode']??null)==='group')$provenance='<p>Источник кадровых данных: '.$e($provenanceData['source']).'<br>Актуально на: '.$e($provenanceData['updatedAt']).'</p>';elseif($f['installers']!==[]){$rows='';foreach($f['installers']as$x)$rows.='<li data-id="'.$e($x['tabId']).'" data-source="'.$e($x['source']).'" data-updated-at="'.$e($x['updatedAt']).'">'.$e($x['fio']).' · Источник кадровых данных: '.$e($x['source']).' · Актуально на: '.$e($x['updatedAt']).'</li>';$provenance='<ul class="fm2-picker-provenance" data-picker-provenance>'.$rows.'</ul>';}else $provenance='';
        $body='<div class="fm2-page-header fm2-order-heading"><div><h1>'.$title.'</h1><p>'.$intro.'</p></div></div>'.$notice.'<form id="form-errors" class="fm2-order-form" method="'.($command?'post':'get').'" action="'.$route.'"'.($command?' enctype="multipart/form-data"':'').'>'.$hidden.'<fieldset class="fm2-order-surface"><header>'.$summary.'</header>'.$upload.'<section class="fm2-order-team" aria-labelledby="installers"><div class="fm2-order-section-head"><div><span class="fm2-order-eyebrow">Шаг 2</span><h2 id="installers">Монтажники</h2><p>'.($changing?'Текущий состав выбран заранее. Добавьте или уберите монтажников для версии '.((int)($f['currentVersion']??0)+1).'.':'Выберите состав, указанный в подписанном распоряжении.').'</p></div></div>'.$provenance.'<div class="fm2-order-selection">'.$installers.'</div></section><aside class="fm2-order-engineer">'.$engineerInfo.'</aside><footer class="fm2-order-actions"><a class="shlz-link" href="/pilot/objects/'.$id.'">Отмена</a>'.$uploadAction.'</footer></fieldset>'.$helper.'</form>';
        $document=PilotView::document($user,$title,'Объекты монтажа',PilotView::breadcrumb([['Объекты монтажа','/pilot/objects'],['Объект монтажа № '.$id,'/pilot/objects/'.$id]],'Распоряжение'),$body,true);
        return \str_replace('</body>','<script src="/pilot/assets/picker.js" defer></script></body>',$document);
    }
    public function renderCompatibility(HttpUser $user,array $f):string
    {
        $configured=$this->render($user,$f);$start=\strpos($configured,'<main class="fm2-main" id="main-content" tabindex="-1">');$end=\strrpos($configured,'</main>');if($start===false||$end===false)throw new \LogicException();$start=\strpos($configured,'>',$start)+1;$body=\substr($configured,$start,$end-$start);$id=PilotView::e($f['id']);
        return '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Загрузить распоряжение — FMonitor 2.0</title><link rel="stylesheet" href="/pilot/assets/shlz.css"></head><body class="shlz-scope"><a class="shlz-link" href="#main-content">Перейти к содержанию</a><header><strong>FMonitor 2.0</strong><span>'.PilotView::e($user->displayName).'</span></header><nav aria-label="Основная навигация"><a class="shlz-link" href="/pilot/">Моя работа</a><span aria-current="page">Объект монтажа № '.$id.'</span></nav><main id="main-content" tabindex="-1">'.$body.'</main><script src="/pilot/assets/navigation.js"></script><script src="/pilot/assets/picker.js" defer></script></body></html>';
